if (estado.distancia < u.distancia.limite) { activas.push("Distancia baja (" + estado.distancia + " < " + u.distancia.limite + " cm)"); if(!debeActuar){debeActuar=true;razon="Distancia por debajo del umbral ("+u.distancia.limite+" cm)";} }

gemelo.alertas_activas = activas;
global.set("gemelo", gemelo);

if (debeActuar) {
    var ultimaAccion = flow.get("ultima_accion_llm") || 0;
