var gemelo = global.get("gemelo");
var payload = msg.payload;
if (!gemelo || !payload || !payload.response) return null;

try {
    var decision = JSON.parse(payload.response);

    msg1 = { payload: {} };
    msg3 = { payload: {} };

    if (decision.activar_led) {
        msg1.payload = { estado: decision.activar_led };
    }

    msg3.payload = {
        nivel: decision.nivel_alerta || "normal",
        razonamiento: decision.razonamiento || "",
        timestamp: new Date().toISOString()
    };

    gemelo.resumen_llm = decision.razonamiento || "";
    gemelo.ultimo_update = new Date().toISOString();
    global.set("gemelo", gemelo);

    node.status({fill:"blue",shape:"dot",text:decision.nivel_alerta});

    return [[msg1], [msg3]];
} catch(e) {
    node.error("Error parseando respuesta LLM: " + e);
    return null;
}

