var b = msg.payload || {};
var disp = b.dispositivo || "led";
var estado = (b.estado === true || b.estado === "true" || b.estado === "ON" || b.estado === 1);
var mqttMsg = { topic: "smarthome/equipo2/control/" + disp, payload: estado ? "ON" : "OFF" };
msg.payload = { ok: true, dispositivo: disp, estado: estado ? "ON" : "OFF" };
msg.statusCode = 200;
return [mqttMsg, msg];

var b = msg.payload || {};
var estado = String(b.status || 'firing').replace(/[^a-zA-Z0-9_-]/g, '');
var titulo = 'alerta';
try { titulo = (b.alerts && b.alerts[0] && b.alerts[0].labels && b.alerts[0].labels.alertname) || b.title || 'alerta'; } catch(e) {}
node.warn('Alerta Grafana: ' + estado + ' - ' + titulo);
var gemelo = global.get('gemelo');
if (gemelo) {
    gemelo.alertas_activas.push('Grafana: ' + titulo + ' (' + estado + ')');
    if (gemelo.alertas_activas.length > 5) gemelo.alertas_activas.shift();
    global.set('gemelo', gemelo);
}
msg.headers = { 'Authorization': 'Token smarthome_token_2024', 'Content-Type': 'text/plain' };
msg.payload = 'alerta_grafana,estado=' + estado + ' valor=1';
return msg;

var texto = String(msg.payload || "").toLowerCase();
var gemelo = global.get("gemelo");
if (!gemelo) return [null, null];
if (!gemelo.umbrales) gemelo.umbrales = { co2:{limite:400,direccion:"mayor",unidad:"ppm"}, sonido:{limite:80,direccion:"mayor",unidad:"dB"}, distancia:{limite:20,direccion:"menor",unidad:"cm"} };

var esComando = /(l[ií]mite|umbral|cr[ií]tic|peligros|establece|pon|deja|cambia|configura|ajusta|fija|setea)/.test(texto);
var sensor = null;
if (/(co2|gas|di[oó]xido|mq7)/.test(texto)) sensor = "co2";
else if (/(sonido|ruido|decibel)/.test(texto)) sensor = "sonido";
else if (/(distancia|proximidad|cercan)/.test(texto)) sensor = "distancia";

var m = texto.match(/\b(\d+(?:[.,]\d+)?)\b/);
var valor = m ? parseFloat(m[1].replace(",", ".")) : null;

if (esComando && sensor && valor !== null && !isNaN(valor)) {
    gemelo.umbrales[sensor].limite = valor;
    gemelo.ultimo_update = new Date().toISOString();
    global.set("gemelo", gemelo);
    var un = gemelo.umbrales[sensor].unidad;
    var dir = gemelo.umbrales[sensor].direccion === "menor" ? "por debajo de" : "por encima de";
    var nombre = sensor === "co2" ? "CO2" : sensor;
    msg.payload = "Listo. El limite critico de " + nombre + " quedo en " + valor + " " + un + ". A partir de ahora se considera peligroso " + dir + " " + valor + " " + un + ".";
    node.status({fill:"blue",shape:"dot",text:nombre + " = " + valor});
    var umbralMsg = { topic: "smarthome/equipo2/umbrales/" + sensor, payload: JSON.stringify({ limite: valor, direccion: gemelo.umbrales[sensor].direccion, unidad: un }), retain: true };
    return [msg, null, umbralMsg];
}
return [null, msg, null];

var gemelo = global.get("gemelo");
if (!gemelo) return null;

