msg.url = env.get('CAMARA_URL') || 'http://172.20.10.8/capture';
// Timeout corto: si la camara no responde, descartar y esperar el proximo tick
msg.requestTimeout = 4000;
return msg;

if (!Buffer.isBuffer(msg.payload) || msg.payload.length < 100) {
    node.status({fill:'red',shape:'ring',text:'camara no disponible'});
    return null;
}
var b64 = msg.payload.toString('base64');
msg.payload = { image: 'data:image/jpeg;base64,' + b64 };
// Conservar la foto para poder guardarla despues desde el dashboard
msg.imagen_b64 = msg.payload.image;
msg.headers = { 'Content-Type': 'application/json' };
