if (total > 0 && msg.imagen_b64) {
    global.set('ultima_captura', {
        image: msg.imagen_b64,
        nombre: nombre,
        reconocida: reconocido,
        timestamp: new Date().toISOString(),
        hora: new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' })
    });
}
node.status({fill: total>0?'blue':'grey', shape:'dot', text: total>0 ? ('persona: '+(nombre||'desconocida')) : 'sin persona'});
msg.payload = { persona: total>0, reconocida: reconocido, nombre: nombre };
return msg;

// Solo actualizar cuando la camara detecto a alguien
if (!msg.payload || !msg.payload.persona) return null;

var reconocida = !!msg.payload.reconocida;
var rec = {
    nombre: reconocida ? msg.payload.nombre : 'Desconocida',
    reconocida: reconocida,
    estado: reconocida ? 'Conocida' : 'DESCONOCIDA',
