};

global.set('ultima_persona', rec);
var gemelo = global.get('gemelo');
if (gemelo) {
    gemelo.ultima_persona = rec;
    global.set('gemelo', gemelo);
}

node.status({ fill: reconocida ? 'green' : 'red', shape: 'dot', text: rec.nombre + ' (' + rec.estado + ')' });
msg.payload = rec;
return msg;

