if (!nombre) {
    return [null, { payload: 'Escribe el nombre antes de guardar' }];
}
msg.payload = { nombre: nombre, image: cap.image };
msg.headers = { 'Content-Type': 'application/json' };
msg.requestTimeout = 20000;
msg.nombre_registro = nombre;
node.status({fill:'blue',shape:'dot',text:'registrando ' + nombre + '...'});
